            new Vector3WithNeighbors(office.x, floorY, office.z - 1);
            nodes[doorNode].addNode(deskNode);

            if (sitTargets) {
                sitTargets[deskNode] = {
                    sit: true,
                    facing: Math.PI, // Face monitor (-Z)
