    function buildLobbyLayout(floorY, shaftX, shaftZ, nodes, sitTargets) {
        const halfW = WORLD.BUILDING_WIDTH / 2;
        const halfD = WORLD.BUILDING_DEPTH / 2;

        // Entrance chain: outside -> front_door_threshold -> entrance -> lobby_center
